static int copyin(struct openpromio __user *info, struct openpromio **opp_p)
{
	int bufsize;

	if (!info || !opp_p)
		return -EFAULT;
	if (get_user(bufsize, &info->oprom_size))
		return -EFAULT;
	if (bufsize == 0)
		return -EINVAL;

	/* Allocate kernel buffer of fixed maximum size OPROMMAXPARAM */
	*opp_p = kmalloc(sizeof(struct openpromio) + OPROMMAXPARAM + 1, GFP_KERNEL);
	if (!*opp_p)
