	memset(*opp_p, 0, sizeof(struct openpromio) + OPROMMAXPARAM + 1);
	(*opp_p)->oprom_size = 0;  

	if (copy_from_user(&(*opp_p)->oprom_array, &info->oprom_array, bufsize)) {
		kfree(*opp_p);
		return -EFAULT;
	}
	(*opp_p)->oprom_size = bufsize;
	return 0;
}
